select month(paid_at) as paid_month, case when method in ('cash', 'promptpay') then 'core' else 'other' end as method_group, sort_array(collect_set(method)) as method_list, round(stddev(amount), 2) as stddev_amount, sum(case when method = 'card' then 1 else 0 end) as card_count from payments where method = 'cash' or order_id in (5, 11, 26, 39) group by paid_month, method_group having card_count > 35 order by stddev_amount desc;
